window.DEX_DATA["sources:backport-fd474ece881a3f01"]={"json":{"skins":[{"filename":"littleboy.png"}],"names":[{"name":"比利"},{"name":"昭彦"},{"name":"罗伯特"},{"name":"萨米"},{"name":"皮普"}],"chat":[{"lines":[{"text":"长大后，我要当宝可梦大师，还要当消防员！"},{"text":"真希望我也能像你一样拥有宝可梦！"}]},{"lines":[{"text":"哇，你的宝可梦是在店里买的，还是亲手捕捉的？"},{"text":"我用纸和胶水做了个精灵球，不过好像不太管用。"}]},{"lines":[{"text":"我爸爸可是有名的宝可梦捕捉高手！"},{"text":"其实，他只是在花园里抓到一只绿毛虫，后来又放走了……"}]},{"lines":[{"text":"看我用网抓宝可梦！前几天我差点就抓到独角虫啦！"},{"text":"总有一天，我要把它们全都抓到！"}]}]}};
